using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;
namespace IdleIntelligence.Runtime {
 // Explicit development-only acceptance run: real clock, UI events and default starting resources.
 public sealed class IsolatedFreshReview:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
  GameRuntime game;readonly List<string> actions=new List<string>();string folder;double started;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(Environment.GetEnvironmentVariable("IDLE_FRESH_REVIEW")!="1")return;GameRuntime.SavePathOverride=Path.Combine(Application.temporaryCachePath,"fresh-review-"+Guid.NewGuid().ToString("N")+".json");var root=new GameObject("IsolatedFreshReview");DontDestroyOnLoad(root);root.AddComponent<IsolatedFreshReview>();}
  void Record(string text){actions.Add((Time.realtimeSinceStartupAsDouble-started).ToString("F3")+" s · "+text);File.WriteAllLines(Path.Combine(folder,"actions.txt"),actions);}
  IEnumerator Press(GameObject target){yield return null;Canvas.ForceUpdateCanvases();var canvas=target.GetComponentInParent<Canvas>().rootCanvas;var camera=canvas.renderMode==RenderMode.ScreenSpaceOverlay?null:canvas.worldCamera;var eventData=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(camera,target.transform.position),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(eventData,hits);var actual=hits.Select(h=>ExecuteEvents.GetEventHandler<IPointerClickHandler>(h.gameObject)).FirstOrDefault();if(actual!=target)throw new InvalidOperationException("Review touch blocked: "+target.name+" by "+actual?.name);ExecuteEvents.Execute(target,eventData,ExecuteEvents.pointerDownHandler);yield return new WaitForSecondsRealtime(.08f);ExecuteEvents.Execute(target,eventData,ExecuteEvents.pointerUpHandler);ExecuteEvents.Execute(target,eventData,ExecuteEvents.pointerClickHandler);Record("UI touch "+target.name);yield return new WaitForSecondsRealtime(.8f);}
  IEnumerator Dialogues(){for(int i=0;i<40&&game.State.Story.open!=null;i++){yield return new WaitForSecondsRealtime(1.1f);var next=GameObject.Find("StoryContinue");if(next==null)throw new InvalidOperationException("Missing Mira continue");yield return Press(next);}}
  IEnumerator Start(){folder=Path.Combine(Application.temporaryCachePath,"idle-fresh-review");Directory.CreateDirectory(folder);started=Time.realtimeSinceStartupAsDouble;while((game=FindFirstObjectByType<GameRuntime>())==null||game.State==null)yield return null;Record("NATURAL isolated fresh save: "+GameRuntime.SavePathOverride+"; default credits="+game.State.Credits+"; no grants, no accelerated time");yield return new WaitForSecondsRealtime(2);GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";yield return Press(GameObject.Find("StoryChooseName"));yield return Dialogues();yield return Press(game.TapButton.gameObject);yield return Dialogues();var guide=GameObject.Find("StoryShowTarget");if(guide!=null)yield return Press(guide);yield return Press(GameObject.Find("hardware-calculator"));yield return Dialogues();guide=GameObject.Find("StoryShowTarget");if(guide!=null)yield return Press(guide);else yield return Press(game.TrainingTab.gameObject);var training=GameObject.Find("training-quality").GetComponent<LearningCard>();yield return Press(training.StartAction.gameObject);if(!game.State.Journal.Has("training-start"))throw new InvalidOperationException("Training did not start");yield return Dialogues();yield return Press(game.ResearchTab.gameObject);game.Content.GetComponentInParent<ScrollRect>().verticalNormalizedPosition=1;yield return new WaitForSecondsRealtime(.5f);var research=GameObject.Find("research-dataGeneration").GetComponent<LearningCard>();yield return Press(research.StartAction.gameObject);if(game.State.Lifetime.researchStarted<1)throw new InvalidOperationException("Research did not start");yield return Dialogues();yield return Press(game.HardwareTab.gameObject);while(Time.realtimeSinceStartupAsDouble-started<180&&GameObject.Find("LootSignal")==null)yield return null;var drone=GameObject.Find("LootSignal");if(drone==null)throw new InvalidOperationException("No natural drone before timeout");yield return new WaitForSecondsRealtime(1);yield return Press(drone);if(game.State.Lifetime.dropsClaimed!=1)throw new InvalidOperationException("Drone claim count");Record("Natural drone saved once; reload next");yield return new WaitForSecondsRealtime(2);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=FindFirstObjectByType<GameRuntime>();if(game.State.Retention.aiName!="AURA"||!game.State.QualityUsed||game.State.Lifetime.dropsClaimed!=1)throw new InvalidOperationException("Fresh review reload mismatch");Record("COMPLETE: reload preserved name, intro flags and one drone reward; commit="+Application.buildGUID);File.WriteAllText(Path.Combine(folder,"complete.txt"),"Actual real-time Unity UI sequence completed; no prepared resources. Save="+game.SavePath);}
#endif
 }
}
